mapper.update:
update ${tableName}
set status = #{data.status},
un_passed_deal = #{data.unPassedDeal},
un_passed_deal_desc = #{data.unPassedDealDesc},
final_un_passed_deal = #{data.finalUnPassedDeal},
final_un_passed_deal_desc = #{data.finalUnPassedDealDesc}

    ,final_status = #{data.finalStatus}


    ,approve_user_code = #{data.approveUserCode}

where enterprise_code = #{enterpriseCode}
and delete_flag = false
and primary_key = #{data.primaryKeyValue}

update ${tableName}
set final_status              = #{data.finalStatus},
    final_un_passed_deal      = #{data.finalUnPassedDeal},
    final_un_passed_deal_desc = #{data.finalUnPassedDealDesc}
where enterprise_code = #{enterpriseCode}
  and delete_flag = false
  and report_main_id = #{data.reportMainId}

mapper.select:
select a.*,
a.primary_key as primaryKeyValue,
b.staff_sign as report_user_name
from ${approveTable} a
left join ${staffTable} b on a.report_user_code = b.primary_key
where a.enterprise_code = #{enterpriseCode}
and a.delete_flag = false

    and a.approve_user_code = #{approveUserCode}


    and (a.approve_user_code = #{approveUserCode} or a.approve_user_code is null)


    and a.buss_number like concat('%', #{data.bussNumber}, '%')


    AND a.status = #{data.status}


    AND a.inspect_type = #{data.inspectType}

order by a.create_time desc

select count(1)
from ${approveTable} a
where a.enterprise_code = #{enterpriseCode}
and a.delete_flag = false
and a.final_status = #{finalStatus}

    and a.approve_user_code = #{approveUserCode}


    and (a.approve_user_code = #{approveUserCode} or a.approve_user_code is null)

select a.*,
       a.primary_key as primaryKeyValue
from ${approveTable} a
where a.primary_key = #{primaryKey}
  and a.enterprise_code = #{enterpriseCode}
  and a.delete_flag = false

select a.*
from ${approveTable} a
where a.inspect_main_id = #{inspectMainId}
  and a.enterprise_code = #{enterpriseCode}
  and a.delete_flag = false
  and a.status = 1
